arguments.command:
rm -f .server_ready; python3 scripts/dev_server.py 0 & sleep 0.5; python3 - <<'EOF'
import urllib.request
port = open('.server_ready').read().strip()
for i in range(4):
    try:
        r = urllib.request.urlopen("http://127.0.0.1:%s/%s" % (port, "app.css"), timeout=5)
        print(i, "first ok", len(r.read()))
    except Exception as e:
        print(i, "first fail", e)
    try:
        r = urllib.request.urlopen("http://127.0.0.1:%s/%s" % (port, "app.css"), timeout=5)
        print(i, "second ok", len(r.read()))
    except Exception as e:
        print(i, "second fail", e)
EOF
kill %1 2>/dev/null; rm -f .server_ready
